if k==1:
    print(min(a))
elif k>3:
    print(max(a))
else:
    for i in range(1, n-1):
        f=min(a[0:i])
        f1=min(a[i+1:len(a)])
        if max(f, f1)>maxi:
            maxi=max(f1, f)
    print(maxi)

